<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Orderly · Order management</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#f6f7f9;color:#17263c;font:15px system-ui,sans-serif}header{background:#12283c;color:white;padding:22px 5%;display:flex;align-items:center;justify-content:space-between}.brand{font-size:25px;font-weight:750;letter-spacing:-1px}.brand b{color:#67d8b4}.tag{font-size:12px;background:#294354;padding:7px 12px;border-radius:20px}main{max-width:1250px;margin:40px auto;padding:0 25px}h1{font-size:31px;letter-spacing:-1px;margin:0 0 8px}p{color:#718092}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:28px}button{background:#157e68;border:0;color:white;padding:12px 18px;border-radius:8px;font:inherit;cursor:pointer}button:hover{filter:brightness(.92)}.secondary{background:#e9edf2;color:#344257}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-bottom:28px}.card{background:white;border:1px solid #e3e8ed;border-radius:12px;padding:22px}.number{font-size:30px;font-weight:700;margin-top:8px}.toolbar{display:flex;gap:12px;margin-bottom:20px}input,select,textarea{border:1px solid #dce2e8;border-radius:7px;padding:11px;font:inherit;background:white;color:inherit}input{min-width:0}.toolbar input{flex:1}table{width:100%;border-collapse:collapse;text-align:left}th{font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#7b8797;padding:16px}td{border-top:1px solid #edf0f3;padding:17px 16px}small{color:#7b8797}td strong{display:block;margin-bottom:4px}.badge{display:inline-block;background:#fff2d6;color:#8a6315;padding:6px 10px;border-radius:20px;font-size:12px}.completed{background:#dff5ec;color:#17634a}.shipped,.processing{background:#e4edff;color:#325d9f}.cancelled{background:#fce6e6;color:#a13939}.link{background:transparent;color:#157e68;padding:4px 0}.tablewrap{overflow:auto;background:white;border:1px solid #e3e8ed;border-radius:12px}.empty{text-align:center;padding:40px;color:#718092}dialog{border:0;border-radius:15px;width:650px;max-width:95vw;padding:28px;box-shadow:0 20px 90px #0003}dialog::backdrop{background:#11263b88}h2{margin-top:0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:15px}label{display:block;font-size:12px;font-weight:650;margin:15px 0 7px}form input,form textarea{width:100%}.item{display:grid;grid-template-columns:1fr 70px 105px 30px;gap:8px;margin:8px 0}.item button{padding:6px;background:#eef1f5;color:#6b7787}.actions{display:flex;justify-content:flex-end;gap:10px;margin-top:25px}.error{color:#b13838;font-size:13px;white-space:pre-line}#toast{position:fixed;bottom:25px;right:25px;background:#12283c;color:white;padding:15px 25px;border-radius:9px;display:none}footer{margin:25px 0;color:#8b96a4;font-size:12px}#detail p{line-height:1.6}.pagination{display:flex;align-items:center;justify-content:flex-end;gap:15px;margin-top:18px}@media(max-width:650px){main{padding:0 15px;margin-top:25px}.cards{gap:8px}.card{padding:14px}.number{font-size:24px}.top{align-items:start}.grid{grid-template-columns:1fr}.toolbar{flex-wrap:wrap}th,td{padding:12px}header{padding:20px}.tag{font-size:10px}}
</style></head><body>
<header><div class="brand">orderly<b>●</b></div><span class="tag">Laravel · Order management</span></header>
<main><div class="top"><div><h1>Orders</h1><p>Every order, from placed to delivered.</p></div><button onclick="openCreate()">＋ New order</button></div>
<div class="cards"><div class="card"><small>Total orders</small><div id="count" class="number">—</div></div><div class="card"><small>Active orders</small><div id="active" class="number">—</div></div><div class="card"><small>Order value · USD</small><div id="value" class="number">—</div></div></div>
<div class="toolbar"><input id="search" placeholder="Search customer name or email" aria-label="Search orders"><select id="filter" aria-label="Filter status"><option value="">All statuses</option><option>pending</option><option>processing</option><option>shipped</option><option>completed</option><option>cancelled</option></select></div>
<div class="tablewrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Status</th><th>Total</th><th>Placed</th><th></th></tr></thead><tbody id="rows"></tbody></table><div id="empty" class="empty" hidden>No orders yet. Create your first order.</div></div><div class="pagination"><button class="secondary" id="prev">Previous</button><small id="page"></small><button class="secondary" id="next">Next</button></div>
<footer>Temporary demo · Shared data · Use sample information only. &nbsp; API: /api/orders</footer></main>
<dialog id="create"><form id="orderForm"><h2>Create an order</h2><small>Add customer details and items. Totals are calculated automatically.</small><div class="grid"><div><label for="name">Customer name</label><input id="name" required maxlength="120"></div><div><label for="email">Email address</label><input id="email" type="email" required></div></div><label>Items · product / quantity / USD price</label><div id="items"></div><button type="button" class="link" onclick="addItem()">＋ Add another item</button><label for="notes">Notes (optional)</label><textarea id="notes" rows="2" maxlength="2000"></textarea><p class="error" id="formError"></p><div class="actions"><button type="button" class="secondary" onclick="document.getElementById('create').close()">Cancel</button><button id="save">Create order</button></div></form></dialog>
<dialog id="detail"><div id="detailBody"></div><p class="error" id="detailError"></p><div class="actions"><button class="secondary" onclick="document.getElementById('detail').close()">Close</button><button id="delete" style="background:#b34c4c">Delete order</button><button id="update">Save status</button></div></dialog><div id="toast" role="status"></div>
<script>
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=c=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(c/100);let page=1,last=1,current;
async function api(path='',options={}){let r=await fetch('/api/orders'+path,{...options,headers:{'Content-Type':'application/json','Accept':'application/json',...options.headers}});if(!r.ok){let e=await r.json();throw Error(e.errors?Object.values(e.errors).flat().join('\n'):e.message||'Request failed')}return r.status===204?null:r.json()}
function toast(t){$('toast').textContent=t;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',3000)}
async function load(){try{let d=await api('?'+new URLSearchParams({page,search:$('search').value,status:$('filter').value}));last=d.last_page;$('rows').innerHTML=d.data.map(o=>`<tr><td><strong>#${String(o.id).padStart(4,'0')}</strong><small>${o.items.length} item${o.items.length===1?'':'s'}</small></td><td><strong>${esc(o.customer_name)}</strong><small>${esc(o.customer_email)}</small></td><td><span class="badge ${esc(o.status)}">${esc(o.status)}</span></td><td>${money(o.total_cents)}</td><td><small>${new Date(o.created_at).toLocaleDateString()}</small></td><td><button class="link" onclick="view(${o.id})">View →</button></td></tr>`).join('');$('empty').hidden=d.data.length>0;let stats=await fetch('/api/orders-summary').then(r=>r.json());$('count').textContent=stats.total;$('active').textContent=stats.active;$('value').textContent=money(stats.value);$('page').textContent=`Page ${page} of ${last}`;$('prev').disabled=page<=1;$('next').disabled=page>=last;}catch(e){toast(e.message)}}
function addItem(){let row=document.createElement('div');row.className='item';row.innerHTML='<input placeholder="Product name" aria-label="Product name" required maxlength="150"><input type="number" aria-label="Quantity" value="1" min="1" max="1000" required><input type="number" aria-label="Unit price in USD" placeholder="0.00" min="0" max="100000" step="0.01" required><button type="button" aria-label="Remove item" onclick="this.parentElement.remove()">×</button>';$('items').append(row)}
function openCreate(){$('orderForm').reset();$('items').innerHTML='';$('formError').textContent='';addItem();$('create').showModal()}
$('orderForm').onsubmit=async e=>{e.preventDefault();let items=[...document.querySelectorAll('.item')].map(row=>{let i=row.querySelectorAll('input');return {name:i[0].value,quantity:Number(i[1].value),unit_price:i[2].value}});$('save').disabled=true;try{await api('',{method:'POST',body:JSON.stringify({customer_name:$('name').value,customer_email:$('email').value,notes:$('notes').value,items})});$('create').close();page=1;await load();toast('Order created')}catch(e){$('formError').textContent=e.message}finally{$('save').disabled=false}};
async function view(id){try{current=await api('/'+id);let o=current;$('detailError').textContent='';$('detailBody').innerHTML=`<h2>Order #${String(o.id).padStart(4,'0')}</h2><p><strong>${esc(o.customer_name)}</strong><br>${esc(o.customer_email)}</p><table><thead><tr><th>Item</th><th>Quantity</th><th>Unit price</th></tr></thead><tbody>${o.items.map(i=>`<tr><td>${esc(i.name)}</td><td>${i.quantity}</td><td>${money(i.unit_price_cents)}</td></tr>`).join('')}</tbody></table><p><strong>Total: ${money(o.total_cents)}</strong></p>${o.notes?`<p>Notes: ${esc(o.notes)}</p>`:''}<label for="status">Order status</label><select id="status">${['pending','processing','shipped','completed','cancelled'].map(s=>`<option ${s===o.status?'selected':''}>${s}</option>`).join('')}</select>`;$('detail').showModal()}catch(e){toast(e.message)}}
$('update').onclick=async()=>{try{await api('/'+current.id,{method:'PATCH',body:JSON.stringify({status:$('status').value})});$('detail').close();load();toast('Status updated')}catch(e){$('detailError').textContent=e.message}};
$('delete').onclick=async()=>{if(!confirm('Delete this order permanently?'))return;try{await api('/'+current.id,{method:'DELETE'});$('detail').close();page=1;load();toast('Order deleted')}catch(e){$('detailError').textContent=e.message}};
let timer;$('search').oninput=()=>{clearTimeout(timer);timer=setTimeout(()=>{page=1;load()},300)};$('filter').onchange=()=>{page=1;load()};$('prev').onclick=()=>{if(page>1){page--;load()}};$('next').onclick=()=>{if(page<last){page++;load()}};load();
</script></body></html>